import { resizeWindow } from 'lib/viewport';

import type { ChromeMessagePayload } from 'models/ChromeMessaging';
import { ChromeMessagingAction } from 'models/ChromeMessaging';
import { EXT_CONNECTION_PREFIX } from 'lib/ChromeUtils';

function ignoreError(): null {
  return null;
}

chrome.runtime.onConnect.addListener((port) => {
  if (port.name.includes(EXT_CONNECTION_PREFIX)) {
    const tabId = parseInt(port.name.replace(EXT_CONNECTION_PREFIX, ''), 10);

    if (chrome.runtime.lastError) {
      ignoreError();
    }

    port.onDisconnect.addListener(async () => {
      await chrome.debugger.detach({ tabId });
    });
  }
});

chrome.commands.onCommand.addListener((command, tab) => {
  const { id } = tab;

  if (command === 'capture-page' && id) {
    chrome.runtime.sendMessage({ action: ChromeMessagingAction.DO_SNAPSHOT }, () => {
      if (chrome.runtime.lastError) {
        ignoreError();
      }
    });
  }
});

chrome.runtime.onMessage.addListener((message: ChromeMessagePayload, sender, sendResponse) => {
  if (message.action === ChromeMessagingAction.RESIZE_WINDOW) {
    // Previous solution without the use of debugger.
    // chrome.windows.getCurrent((window) => {
    //   if (window.id !== undefined) {
    //     const updateInfo: chrome.windows.UpdateInfo = {
    //       width: message.size.width,
    //       height: message.size.height,
    //       state: 'normal',
    //     };
    //     chrome.windows.update(window.id, updateInfo);
    //     sendResponse('resized');
    //   }
    // });
    resizeWindow(message).then(() => {
      sendResponse('resized');
    });
    return true;
  }
  return false;
});
