import { getTabId } from 'lib/ChromeUtils';
import { getPageViewport } from 'lib/Utils';
import type { ChromeMsgResizeWindow } from 'models/ChromeMessaging';

/**
 * Resize the viewport through DevtoolsProtocol 'Emulation.setDeviceMetricsOverride'.
 * Requires to attach a debugger to work.
 */
export async function resizeWindow(message: ChromeMsgResizeWindow): Promise<void> {
  const { device } = message;
  const tabId = await getTabId();

  let alreadyAttached = false;
  await new Promise<void>((resolve) => {
    chrome.debugger.attach({ tabId }, '1.3', () => {
      if (chrome.runtime.lastError) {
        if (chrome.runtime.lastError.message?.includes('debugger is already attached')) {
          alreadyAttached = true;
        }
      }
      resolve();
    });
  });

  const pageViewport = await getPageViewport();
  if (
    !alreadyAttached ||
    pageViewport?.outerHeight !== device.viewport.height ||
    pageViewport?.outerWidth !== device.viewport.width
  ) {
    await new Promise<void>((resolve) => {
      chrome.debugger.sendCommand(
        { tabId },
        'Emulation.setDeviceMetricsOverride',
        {
          width: device.viewport.width,
          height: device.viewport.height,
          // screenWidth: message.size.width,
          // screenHeight: message.size.height,
          deviceScaleFactor: 0,
          mobile: device.viewport.touch ?? false,
          positionX: 0,
          positionY: 0,
          /**
           * This settings seems to avoid Chrome graphic issues
           * when devtools is open
           */
          dontSetVisibleSize: true,
        },
        () => {
          if (chrome.runtime.lastError) {
            console.error(chrome.runtime.lastError);
          }
          resolve();
        },
      );
    });

    await new Promise<void>((resolve) => {
      chrome.debugger.sendCommand(
        { tabId },
        'Emulation.setTouchEmulationEnabled',
        {
          enabled: device.viewport.touch,
        },
        () => {
          if (chrome.runtime.lastError) {
            console.error(chrome.runtime.lastError);
          }
          resolve();
        },
      );
    });

    if (message.reload) {
      await new Promise<void>((resolve) => {
        chrome.debugger.sendCommand(
          { tabId },
          'Page.reload',
          {
            ignoreCache: true,
          },
          () => {
            if (chrome.runtime.lastError) {
              console.error(chrome.runtime.lastError);
            }
            resolve();
          },
        );
      });
    }
  }
}
